Given two sorted arrays arr1[] of size n and arr2[] of size m. Merge these two arrays.After the merge, the first n smallest elements of the combined sorted array should be stored in arr1[], and the remaining m largest elements should be stored in arr2[]. After the merging process, both arr1[] and arr2[] must remain sorted in non-decreasing order.Examples: Input: arr1[] = [1, 3, 4, 5], arr2[] = [2, 4, 6, 8] Output: arr1[] = [1, 2, 3, 4], arr2[] = [4 5, 6, 8] Explanation: Combined sorted array = [1, 2, 3, 4, 4, 5, 6, 8], array arr1[] contains smallest 4 elements: 1, 2, 3, 4, and array arr2[] contains the remaining 4 elements: 4, 5, 6, 8.Input: arr1[] = [5, 8, 9], arr2[] = [4, 7, 8] Output: arr1[] = [4, 5, 7], arr2[] = [8, 8, 9] Explanation: Combined sorted array = [4, 5, 7, 8, 8, 9], array arr1[] contains smallest 3 elements: 4, 5, 7, and array arr2[] contains the remaining 3 elements: 8, 8, 9.Try It YourselfTable of Content[Naive Approach] Concatenate and Sort - O((n + m) log(n + m)) Time and O(n + m) Space[Expected Approach] Two-Pointer Merge - O(n + m) Time and O(n + m) Space[Naive Approach] Concatenate and Sort - O((n + m) log(n + m)) Time and O(n + m) SpaceThe idea is to combine both sorted arrays into a single temporary array, then sort this combined array to get all elements in non-decreasing order. Once sorted, the first n smallest elements are copied back into arr1, and the remaining m largest elements are placed into arr2.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

void mergeArrays(vector<int>& arr1, vector<int>& arr2) {
    int n = arr1.size();
    int m = arr2.size();

    // temporary array to store all elements 
    // from arr1 and arr2
    vector<int> merged(n + m);

    // copy elements from arr1 and arr2 into merged array
    for (int i = 0; i < n; ++i) {
        merged[i] = arr1[i];
    }
    for (int j = 0; j < m; ++j) {
        merged[n + j] = arr2[j];
    }

    // dort the merged array
    sort(merged.begin(), merged.end());

    // distribute first n elements to arr1
    for (int i = 0; i < n; ++i) {
        arr1[i] = merged[i];
    }

    // distribute remaining m elements to arr2
    for (int j = 0; j < m; ++j) {
        arr2[j] = merged[n + j];
    }
}

int main() {
    vector<int> arr1 = {1, 3, 5, 7};
    vector<int> arr2 = {2, 4, 6, 8};

    mergeArrays(arr1, arr2);

    for (int num : arr1) {
        cout << num << ' ';
    }
    cout << endl;

    for (int num : arr2) {
        cout << num << ' ';
    }
    cout << endl;

    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>

// function to compare two integers (used in qsort)
int compare(void* a, void* b) {
    return (*(int*)a - *(int*)b);
}

// function to merge two sorted arrays in-place
void mergeArrays(int arr1[], int arr2[], int n, int m) {
    // temporary array to store all elements 
    // from arr1 and arr2
    int* merged = (int*)malloc((n + m) * sizeof(int));

    // copy elements from arr1 and arr2 into merged array
    for (int i = 0; i < n; ++i) {
        merged[i] = arr1[i];
    }
    for (int j = 0; j < m; ++j) {
        merged[n + j] = arr2[j];
    }

    // sort the merged array
    qsort(merged, n + m, sizeof(int), compare);

    // distribute first n elements to arr1
    for (int i = 0; i < n; ++i) {
        arr1[i] = merged[i];
    }

    // distribute remaining m elements to arr2
    for (int j = 0; j < m; ++j) {
        arr2[j] = merged[n + j];
    }

    // free dynamically allocated memory
    free(merged);
}

int main() {
    int arr1[] = {1, 3, 5, 7};
    int arr2[] = {2, 4, 6, 8};
    int n = sizeof(arr1) / sizeof(arr1[0]);
    int m = sizeof(arr2) / sizeof(arr2[0]);

    mergeArrays(arr1, arr2, n, m);

    for (int i = 0; i < n; ++i) {
        printf("%d ", arr1[i]);
    }
    printf("\n");

    for (int i = 0; i < m; ++i) {
        printf("%d ", arr2[i]);
    }
    printf("\n");

    return 0;
}


