[Expected Approach] Two Pointer Merge - O(n + m) Time and O(n + m) SpaceThe idea is to use the two-pointer to merge both sorted arrays into a temporary array in linear time. We compare elements from arr1 and arr2 one by one and append the smaller element to the merged array. After merging, we copy the first n elements back to arr1 and the remaining m elements to arr2.Step-by-Step Implementation:Initialize two pointers: i = 0 for traversing arr1, j = 0 for traversing arr2Create an empty array merged = []Merge the elements into merged: While both i < n and j < m:=> If arr1[i] <= arr2[j], append arr1[i] to merged and increment i=> Else, append arr2[j] to merged and increment jAppend remaining elements (if any):=> While i < n, append arr1[i] to merged and increment i=> While j < m, append arr2[j] to merged and increment jDistribute the merged elements back:=> Copy the first n elements of merged to arr1=> Copy the remaining m elements to arr2
            C++

    #include <iostream>
#include <vector>
using namespace std;

void mergeArrays(vector<int>& arr1, vector<int>& arr2) {
    int n = arr1.size();
    int m = arr2.size();
    int i = 0, j = 0;

    // temporary array to store merged result
    vector<int> merged;

    // merge elements in sorted order
    while (i < n && j < m) {
        if (arr1[i] <= arr2[j]) {
            merged.push_back(arr1[i++]);
        } else {
            merged.push_back(arr2[j++]);
        }
    }

    // copy remaining elements from arr1
    while (i < n) merged.push_back(arr1[i++]);

    // copy remaining elements from arr2
    while (j < m) merged.push_back(arr2[j++]);

    // copy first n to arr1
    for (int k = 0; k < n; ++k) {
        arr1[k] = merged[k];
    }

    // copy remaining m to arr2
    for (int k = 0; k < m; ++k) {
        arr2[k] = merged[n + k];
    }
}

int main() {
    vector<int> arr1 = {1, 3, 5, 7};
    vector<int> arr2 = {2, 4, 6, 8};

    mergeArrays(arr1, arr2);

    for (int num : arr1) cout << num << ' ';
    cout << endl;
    for (int num : arr2) cout << num << ' ';
    cout << endl;

    return 0;
}


